/**
 * lib/services/bloomberg-originals/store.ts
 *
 * Server-side loader for the Bloomberg Originals country index (lib/data/bloomberg-originals/videos.json),
 * generated by scripts/build-bloomberg-originals.ts. Context, not signal: it lists favourable theses
 * and risks Bloomberg covered per country; it does not feed any score and does not predict prices.
 */

import fs from 'fs';
import path from 'path';

export type BloombergStance = 'favorable' | 'riesgo' | 'mixto' | 'neutral';

export interface BloombergVideo {
  id: string;
  title: string;
  /** YYYY-MM-DD, approximate (derived from YouTube's "N months ago"). */
  published: string | null;
  views: number | null;
  countries: string[];
  companies: { name: string; ticker: string | null }[];
  sectors: string[];
  stance: BloombergStance;
  /** One-line investment angle in Spanish. */
  thesis: string;
}

export interface BloombergOriginalsFile {
  source: string;
  channelId: string;
  generatedAt: string;
  since: string;
  datesApproximate: boolean;
  videos: BloombergVideo[];
}

/** Investment-relevant fact from a transcript, with its verbatim quote (hand-curated, lib/data/bloomberg-originals/country-signals.json). */
export interface CountrySignal {
  category: string;
  /** Slug of the funcionalidades ficha that should absorb this signal, null if none exists yet. */
  ficha: string | null;
  videoId: string;
  claim: string;
  quote: string;
}

export interface CountryBloombergPayload {
  country: string;
  source: string;
  generatedAt: string;
  note: string;
  totals: Record<BloombergStance | 'videos', number>;
  companies: { name: string; ticker: string | null; mentions: number }[];
  sectors: { name: string; mentions: number }[];
  signals: CountrySignal[];
  videos: (BloombergVideo & { url: string })[];
}

const DATA_FILE = path.join(process.cwd(), 'lib', 'data', 'bloomberg-originals', 'videos.json');
const SIGNALS_FILE = path.join(process.cwd(), 'lib', 'data', 'bloomberg-originals', 'country-signals.json');
let cache: BloombergOriginalsFile | null = null;

function loadSignals(file: string = SIGNALS_FILE): Record<string, CountrySignal[]> {
  try {
    return JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch {
    return {};
  }
}

export function loadBloombergFile(file: string = DATA_FILE): BloombergOriginalsFile | null {
  if (cache) return cache;
  try {
    cache = JSON.parse(fs.readFileSync(file, 'utf8')) as BloombergOriginalsFile;
    return cache;
  } catch {
    return null;
  }
}

export function resetBloombergCache(): void {
  cache = null;
}

function rank<T extends { mentions: number }>(map: Map<string, T>): T[] {
  return [...map.values()].sort((a, b) => b.mentions - a.mentions);
}

export function getBloombergForCountry(
  iso2: string,
  data: BloombergOriginalsFile | null = loadBloombergFile(),
  signals: Record<string, CountrySignal[]> = loadSignals()
): CountryBloombergPayload | null {
  if (!data) return null;
  const code = iso2.toUpperCase();
  const videos = data.videos
    .filter(v => v.countries.includes(code))
    .sort((a, b) => (b.published ?? '').localeCompare(a.published ?? ''));

  const totals = { videos: videos.length, favorable: 0, riesgo: 0, mixto: 0, neutral: 0 };
  const companies = new Map<string, { name: string; ticker: string | null; mentions: number }>();
  const sectors = new Map<string, { name: string; mentions: number }>();

  for (const v of videos) {
    totals[v.stance]++;
    for (const c of v.companies) {
      const key = (c.ticker ?? c.name).toUpperCase();
      const entry = companies.get(key) ?? { name: c.name, ticker: c.ticker, mentions: 0 };
      entry.mentions++;
      companies.set(key, entry);
    }
    for (const s of v.sectors) {
      const key = s.toLowerCase();
      const entry = sectors.get(key) ?? { name: s, mentions: 0 };
      entry.mentions++;
      sectors.set(key, entry);
    }
  }

  return {
    country: code,
    source: data.source,
    generatedAt: data.generatedAt,
    note: 'Contexto, no señal: temas que Bloomberg Originals cubrió sobre el país. No entra al score ni predice precios. Fechas aproximadas.',
    totals,
    companies: rank(companies),
    sectors: rank(sectors),
    signals: signals[code] ?? [],
    videos: videos.map(v => ({ ...v, url: `https://www.youtube.com/watch?v=${v.id}` })),
  };
}
